#include <stdio.h>
#include <stdlib.h>

int cmp_desc(const void *a, const void *b) {
    unsigned long long x = *(const unsigned long long *)a;
    unsigned long long y = *(const unsigned long long *)b;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;
    int *x = (int *)malloc((N + 1) * sizeof(int));
    int *y = (int *)malloc((N + 1) * sizeof(int));
    x[0] = 0;
    y[0] = 0;
    for (int i = 1; i <= N; i++) {
        scanf("%d %d", &x[i], &y[i]);
    }

    int total_edges = N * N;
    unsigned long long *edges = (unsigned long long *)malloc(total_edges * sizeof(unsigned long long));
    int idx = 0;

    // Edges from origin (0) to tents
    for (int v = 1; v <= N; v++) {
        int dx = x[v] - x[0];
        int dy = y[v] - y[0];
        int w = dx * dx + dy * dy;
        unsigned long long pack = ((unsigned long long)w << 22) | ((unsigned long long)0 << 11) | (unsigned long long)v;
        edges[idx++] = pack;
    }

    // Edges between tents
    for (int u = 1; u <= N; u++) {
        for (int v = 1; v <= N; v++) {
            if (u == v) continue;
            int dx = x[u] - x[v];
            int dy = y[u] - y[v];
            int w = dx * dx + dy * dy;
            unsigned long long pack = ((unsigned long long)w << 22) | ((unsigned long long)u << 11) | (unsigned long long)v;
            edges[idx++] = pack;
        }
    }

    qsort(edges, total_edges, sizeof(unsigned long long), cmp_desc);

    int *dp = (int *)malloc((N + 1) * sizeof(int));
    int *best = (int *)malloc((N + 1) * sizeof(int));
    int *list = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 0; i <= N; i++) {
        dp[i] = -1;
        best[i] = -1;
    }
    dp[0] = 0;

    int i = 0;
    while (i < total_edges) {
        unsigned long long w = edges[i] >> 22;
        int j = i;
        while (j < total_edges && (edges[j] >> 22) == w) {
            j++;
        }

        int list_size = 0;
        for (int k = i; k < j; k++) {
            unsigned long long pack = edges[k];
            int u = (pack >> 11) & 0x7FF;
            int v = pack & 0x7FF;
            if (dp[u] >= 0) {
                int cand = dp[u] + 1;
                if (cand > best[v]) {
                    if (best[v] == -1) {
                        list[list_size++] = v;
                    }
                    best[v] = cand;
                }
            }
        }

        for (int k = 0; k < list_size; k++) {
            int v = list[k];
            if (best[v] > dp[v]) {
                dp[v] = best[v];
            }
            best[v] = -1;
        }

        i = j;
    }

    int ans = 0;
    for (int v = 1; v <= N; v++) {
        if (dp[v] > ans) ans = dp[v];
    }
    printf("%d\n", ans);

    free(x);
    free(y);
    free(edges);
    free(dp);
    free(best);
    free(list);
    return 0;
}
```

